CREATE TABLE proxy_binding(singleton INTEGER PRIMARY KEY CHECK(singleton=1),instance_id TEXT NOT NULL,generation TEXT NOT NULL,base_url TEXT NOT NULL,blocked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE proxy_conversations(thread_id TEXT PRIMARY KEY REFERENCES conversations(thread_id),request_key TEXT NOT NULL UNIQUE,request_json TEXT NOT NULL,send_started INTEGER NOT NULL DEFAULT 0,operation_id TEXT,conversation_id TEXT UNIQUE,workspace_id TEXT,state TEXT NOT NULL DEFAULT 'NEW');
CREATE TABLE remote_operations(request_key TEXT PRIMARY KEY,kind TEXT NOT NULL,target TEXT NOT NULL,request_digest TEXT NOT NULL,request_json TEXT,send_started INTEGER NOT NULL DEFAULT 0,operation_id TEXT,resource_id TEXT,state TEXT NOT NULL DEFAULT 'NEW');
CREATE TABLE resource_deliveries(id TEXT PRIMARY KEY,thread_id TEXT NOT NULL REFERENCES conversations(thread_id),resource_type TEXT NOT NULL,resource_id TEXT NOT NULL,request_key TEXT NOT NULL UNIQUE,display_name TEXT,sha256 TEXT,size_bytes INTEGER,lease_id TEXT,hold_until TEXT,state TEXT NOT NULL DEFAULT 'WAITING',message_id TEXT,error_code TEXT,created_at INTEGER NOT NULL);
CREATE INDEX resource_delivery_queue ON resource_deliveries(state,created_at);
